mapper.select:
SELECT FROM support_reply r
r.support_inquiry_id = #{no}
ORDER BY r.support_reply_id

mapper.update:
UPDATE support_reply
SET content = #{body, jdbcType=CLOB}, updated_at = CAST(SYSTIMESTAMP AT TIME ZONE 'Asia/Seoul' AS TIMESTAMP)
WHERE support_reply_id = #{replyId} AND support_inquiry_id = #{no}
